      "svg": "<svg viewBox='0 0 1100 1100'><rect width='1100' height='1100' fill='#1a1a2e'/><text x='550' y='70' font-size='34' fill='#ffd700' text-anchor='middle' font-weight='bold'>Martin vs. Elena: 40 Working Years</text><text x='100' y='200' font-size='26' fill='#ffffff'>Martin (Deferrer)</text><rect x='100' y='220' width='900' height='50' fill='#6366f1'/><circle cx='1000' cy='245' r='16' fill='#ef4444'/><text x='1000' y='300' font-size='18' fill='#ef4444' text-anchor='middle'>Retirement at 65:</text><text x='1000' y='325' font-size='16' fill='#888' text-anchor='middle'>all freedom concentrated here</text><text x='100' y='430' font-size='26' fill='#ffffff'>Elena (New Rich)</text><rect x='100' y='450' width='900' height='50' fill='#6366f1'/><circle cx='250' cy='475' r='14' fill='#10b981'/><circle cx='430' cy='475' r='14' fill='#10b981'/><circle cx='610' cy='475' r='14' fill='#10b981'/><circle cx='790' cy='475' r='14' fill='#10b981'/><circle cx='970' cy='475' r='14' fill='#10b981'/><text x='550' y='550' font-size='18' fill='#10b981' text-anchor='middle'>Each dot: a distributed month-long trip or extended break</text><text x='550' y='680' font-size='21' fill='#ffffff' text-anchor='middle'>Same 40-year span, comparable lifetime income</text><text x='550' y='720' font-size='22' fill='#ffd700' text-anchor='middle' font-weight='bold'>Concentrated risk vs. distributed risk</text></svg>",
